#!/usr/bin/env node
// Generated by gadriel-cli — DO NOT EDIT BY HAND.
// Re-run `gadriel code init --upgrade` to refresh.
//
// Gadriel Claude Code statusline.
//
// Prints a single line (no trailing newline) describing the current security
// posture of the repo:
//
//   [GADRIEL] rules=<N> | scans=<N>/day | findings=<N> (<critical>!) | fp_rate=<X>%
//
// Source of truth:
//   $CLAUDE_PROJECT_DIR/.security/metrics/gadriel-progress.json
//   $CLAUDE_PROJECT_DIR/.security/metrics/scan-activity.json
//   $CLAUDE_PROJECT_DIR/.security/metrics/learning.json
//
// Robustness:
//   - Any missing or malformed file degrades to `?` for that field; the script
//     NEVER throws and ALWAYS exits 0.
//   - ANSI coloring is ON by default (Claude Code pipes stdout, so an isTTY
//     check would suppress colors in production). Set NO_COLOR=1 in the env
//     to disable colors (e.g. for log capture).
//   - Per-segment palette: dim `|` separators, dim `rules=N`, cyan `scans`
//     when active else dim, severity-based color on `findings`, and a
//     traffic-light color on `fp_rate` (green <5, yellow <15, red otherwise).

'use strict';

const fs = require('fs');
const path = require('path');

const COLOR_ENABLED = !process.env.NO_COLOR;

// BUG-019: each ANSI value MUST include the escape prefix (`\x1b`,
// i.e. the ESC byte 0x1b) — without it the terminal sees the literal
// bracket-codes `[36m` etc. as plain text rather than as a color
// directive, and the statusline renders as visible bracket-garbage.
const ANSI = {
  reset:  '\x1b[0m',
  red:    '\x1b[31m',
  yellow: '\x1b[33m',
  green:  '\x1b[32m',
  cyan:   '\x1b[36m',
  dim:    '\x1b[2m',
};

function paint(color, text) {
  if (!COLOR_ENABLED) return text;
  const code = ANSI[color];
  if (!code) return text;
  return code + text + ANSI.reset;
}

function projectRoot() {
  return (
    process.env.CLAUDE_PROJECT_DIR ||
    process.env.GADRIEL_PROJECT_ROOT ||
    process.cwd()
  );
}

function readJsonSafe(absPath) {
  try {
    const raw = fs.readFileSync(absPath, 'utf8');
    if (!raw || !raw.trim()) return null;
    return JSON.parse(raw);
  } catch (_) {
    return null;
  }
}

function numOrQuestion(value) {
  if (value === null || value === undefined) return '?';
  if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  if (typeof value === 'string' && value.trim() !== '') return value;
  return '?';
}

function formatPercent(value) {
  if (value === null || value === undefined) return '?';
  if (typeof value !== 'number' || !Number.isFinite(value)) return '?';
  // Accept either 0-1 or 0-100 inputs; normalize to 0-100 with one decimal.
  const pct = value <= 1 ? value * 100 : value;
  return pct.toFixed(1);
}

// Iter-138: traffic-light coloring for fp_rate.
// `rateStr` is the formatted percent string (e.g. "3.2") or '?'.
function colorFpRate(rateStr) {
  const label = `fp_rate=${rateStr}%`;
  if (rateStr === '?') return paint('dim', label);
  const n = Number.parseFloat(rateStr);
  if (!Number.isFinite(n)) return paint('dim', label);
  if (n < 5) return paint('green', label);
  if (n < 15) return paint('yellow', label);
  return paint('red', label);
}

// Iter-138: cyan when scans>0 (active), dim when 0 or unknown.
// `scansStr` is the formatted scan count string (e.g. "12") or '?'.
function colorScans(scansStr) {
  const label = `scans=${scansStr}/day`;
  if (scansStr === '?') return paint('dim', label);
  const n = Number.parseInt(scansStr, 10);
  if (!Number.isFinite(n) || n <= 0) return paint('dim', label);
  return paint('cyan', label);
}

function buildLine() {
  const root = projectRoot();
  const metricsDir = path.join(root, '.security', 'metrics');

  const progress = readJsonSafe(path.join(metricsDir, 'gadriel-progress.json')) || {};
  const activity = readJsonSafe(path.join(metricsDir, 'scan-activity.json')) || {};
  const learning = readJsonSafe(path.join(metricsDir, 'learning.json')) || {};

  const rules    = numOrQuestion(progress.rules_loaded);
  const scans    = numOrQuestion(activity.scans_today);
  const findings = numOrQuestion(activity.findings_total);
  const critical = typeof activity.critical === 'number' ? activity.critical : 0;
  const high     = typeof activity.high === 'number' ? activity.high : 0;
  const fpRate   = formatPercent(learning.false_positive_rate);

  // Severity coloring on the findings segment.
  let findingsSegment;
  if (critical > 0) {
    findingsSegment = paint('red', `findings=${findings} (${critical}!)`);
  } else if (high > 0) {
    findingsSegment = paint('yellow', `findings=${findings} (${critical}!)`);
  } else if (findings === '0' || findings === 0) {
    findingsSegment = paint('green', `findings=${findings} (${critical}!)`);
  } else {
    findingsSegment = `findings=${findings} (${critical}!)`;
  }

  const label  = paint('cyan', '[GADRIEL]');
  const rulesS = paint('dim', `rules=${rules}`);
  const scansS = colorScans(scans);
  const fpS    = colorFpRate(fpRate);
  const sep    = paint('dim', ' | ');

  return `${label} ${rulesS}${sep}${scansS}${sep}${findingsSegment}${sep}${fpS}`;
}

function main() {
  let line = '';
  try {
    line = buildLine();
  } catch (_) {
    // Last-ditch fallback — never throw, never crash a statusline render.
    line = '';
  }
  try {
    // No trailing newline — Claude Code renders the statusline verbatim.
    process.stdout.write(line);
  } catch (_) { /* swallow */ }
}

try {
  main();
} catch (_) {
  // truly nothing escapes
}

process.exit(0);
